def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    ones = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 1]
    sixes = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 6]

    bridges = []
    for i, (r1, c1) in enumerate(ones):
        for r2, c2 in ones[i + 1:]:
            dr, dc = r2 - r1, c2 - c1
            if dr == 0 or abs(dr) != abs(dc):
                continue
            sr = 1 if dr > 0 else -1
            sc = 1 if dc > 0 else -1
            cells = []
            r, c = r1, c1
            while True:
                cells.append((r, c))
                if (r, c) == (r2, c2):
                    break
                r += sr
                c += sc
            bridges.append((cells, sr == sc))

    for cells, _ in bridges:
        for r, c in cells:
            if grid[r][c] != 6:
                out[r][c] = 1

    # A 6 on a bridge draws the perpendicular diagonal across the grid.
    for r, c in sixes:
        orientations = {
            same_slope
            for cells, same_slope in bridges
            if (r, c) in cells
        }
        for same_slope in orientations:
            for rr in range(h):
                if same_slope:
                    # Bridge runs down-right; draw down-left / up-right.
                    cc = r + c - rr
                else:
                    # Bridge runs down-left; draw down-right / up-left.
                    cc = rr + (c - r)
                if 0 <= cc < w and grid[rr][cc] not in (1, 6):
                    out[rr][cc] = 6

    return out
